using UnityEngine;
public class Spin : MonoBehaviour {
    public float speed = 45f;
    private float phase = 0f;
    void Start() { Debug.Log("spin " + gameObject.name); transform.position = new Vector3(1, 2, 3); }
    void Update() {
        transform.Rotate(0, speed * Time.deltaTime, 0);
        phase += Time.deltaTime;
        float bob = Mathf.Sin(phase * 2f) * 0.5f;
        transform.position = new Vector3(1f, 2f + bob, 3f);
        if (phase > 5f) { renderer.material.color = new Color(1, 0, 0); }
        for (var i = 0; i < 3; i++) { phase += 0f; }
        var other = GameObject.Find("Floor");
        if (other != null && Vector3.Distance(transform.position, other.position) < 3f) { transform.localScale = new Vector3(2,2,2); }
    }
}

